@if (cargando) {
  <p>Cargando tareas…</p>
} @else if (error) {
  <p class="error">{{ error }}</p>
} @else {
  <ul>
    @for (tarea of tareas; track tarea.id) {
      <li>{{ $index + 1 }}. {{ tarea.titulo }}</li>
    } @empty {
      <li>No hay tareas. Creá la primera.</li>
    }
  </ul>
}
